function readMailjetMessage(message) {
  if (
    !message ||
    typeof message !== "object" ||
    Array.isArray(message) ||
    message.Status !== "success"
  )
    throw new Error("Mailjet did not accept the message");
  if (
    !Array.isArray(message.To) ||
    message.To.length !== 1 ||
    message.To.some(
      (recipient) =>
        !recipient ||
        typeof recipient.Email !== "string" ||
        !(
          (typeof recipient.MessageID === "number" && Number.isFinite(recipient.MessageID)) ||
          (typeof recipient.MessageID === "string" && recipient.MessageID)
        ) ||
        typeof recipient.MessageUUID !== "string" ||
        !recipient.MessageUUID,
    )
  )
    throw new Error("Mailjet returned no accepted recipient identifier");
  return message;
}
function emailResult({ body, statusCode, bodyEncoding }) {
  if (statusCode !== 200 || bodyEncoding)
    throw new Error("Mailjet did not return a completed Send API result (HTTP " + statusCode + ")");
  if (!body || !Array.isArray(body.Messages) || body.Messages.length !== 1)
    throw new Error("Mailjet returned an unexpected message batch");
  return { message: readMailjetMessage(body.Messages[0]) };
}

